def transform(grid):
    h, w = len(grid), len(grid[0])
    # Find a full monochrome divider and keep the region before it.
    for r, row in enumerate(grid):
        if len(set(row)) == 1 and row[0] != 0:
            return [[2 if v != 0 else 0 for v in line] for line in grid[:r]]
    for c in range(w):
        vals = [grid[r][c] for r in range(h)]
        if len(set(vals)) == 1 and vals[0] != 0:
            return [[2 if grid[r][j] != 0 else 0 for j in range(c)] for r in range(h)]
    return grid

